pseudocode:
1. function longestSubstring(s, k) {
2.   if (s.length < k) return 0;
3.   let counts = {};
4.   for (let char of s) counts[char] = (counts[char] || 0) + 1;
5.   for (let char in counts) {
6.     if (counts[char] < k) {
7.       return Math.max(...s.split(char).map(sub => longestSubstring(sub, k)));
8.     }
9.   }
10.  return s.length;
11. }
